// Extract offboarding data from webhook payload
const payload = $input.first().json;
const employeeId = payload.employee_id;
const exitType = payload.exit_type || 'resignation';
const lastWorkingDay = payload.last_working_day;
const initiatedBy = payload.initiated_by;
const firstName = payload.first_name;
const lastName = payload.last_name;
const email = payload.email;
const department = payload.department;
const position = payload.position;

return [{ 
  json: { 
    employee_id: employeeId,
    exit_type: exitType,
    last_working_day: lastWorkingDay,
    initiated_by: initiatedBy,
    first_name: firstName,
    last_name: lastName,
    email: email,
    department: department,
    position: position,
    full_name: `${firstName} ${lastName}`
  } 
}];

// Store offboarding ID for next steps
const offboardingId = $input.first().json.id;
const employeeData = $('Parse_Offboarding_Data').first().json;

return [{ 
  json: { 
    ...employeeData,
    offboarding_id: offboardingId
  } 
}];

